-- Cafe Barra routes restore
-- Source: local_db_20260513_200917.sql  |  Scope: company 58b2b15b-bada-4bcd-9c12-b7e66a37d0bc ONLY
-- Replaces the 5 generic recovery-seed routes with the 10 real B2B operator routes.
-- May-13 dump predates the 'level' column, so routes are inserted (level defaults to 'leg')
-- then promoted to level='route' and renumbered 1-10. All-or-nothing transaction.
BEGIN;

-- 1. remove the 5 placeholder seed routes (exact UUIDs)
DELETE FROM public.routes WHERE company_id='58b2b15b-bada-4bcd-9c12-b7e66a37d0bc' AND id IN ('cbcc224a-826d-4f22-bd3e-fb98515f0562','d235af1c-83a2-4f72-b186-516571cb007d','76c79f05-d9a0-4272-817e-e2214b7b145a','a5b18726-782c-4978-9ae4-e594daca7c2f','e2df74c0-adc5-4a1a-96bd-f8b0cc912894');

-- 2. insert the 10 real routes verbatim from backup (new columns take schema defaults)
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('f0fac021-4944-4f9e-a296-3e9f8833486f', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', 'fd766480-d2ef-4794-a79a-b849a91df024', 'fix', 'Reduce reorder friction caused by unclear supplier terms', 'Supplier terms on lead times and pricing tiers are not consistently documented, creating friction in the reorder cycle and contributing to stock-out risk.', 7, 'low', 'Fix', 1, '2026-05-13 19:04:00.517997+00', '2026-05-13 22:14:06.283762+00', '{ODI,strategy_cascade,reconstructed_prior,superseded_by_evidence_78e,superseded_by_evidence_79}', '[{"id": "s1", "title": "Audit current supplier contracts for ambiguous clauses", "status": "complete"}, {"id": "s2", "title": "Draft standardized lead-time and pricing addendum", "status": "in_progress"}, {"id": "s3", "title": "Review addendum with supplier and sign updated terms", "status": "missing"}]', '[{"id": "e1", "title": "Supplier communication logs (6 months)", "status": "complete"}, {"id": "e2", "title": "Stock-out incident log cross-referenced with reorder timing", "status": "in_progress"}, {"id": "e3", "title": "Signed updated supplier agreement", "status": "missing"}]', '["Unclear terms may be creating avoidable stock-out risk on high-volume SKUs.", "Formalizing lead-time windows and pricing tier thresholds could reduce ad-hoc renegotiation.", "Directly addresses the gap in step 4 (Select suppliers) of the specialty coffee sourcing job."]', 'stale', 'unvalidated', 'partial', NULL, 'Replaced by evidence-derived routes from Phase 79 active file analysis', NULL, NULL, NULL, '{}', '{}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('49318645-d804-4c83-b7fe-e5cbe01a607e', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', 'fd766480-d2ef-4794-a79a-b849a91df024', 'create', 'Test whether operational proof changes repeat purchasing confidence', 'Current proof of operational reliability is mostly public signals. This route tests whether building direct, documented partner proof changes repeat purchasing confidence.', 9, 'medium', 'Create', 5, '2026-05-13 19:04:00.517997+00', '2026-05-13 22:14:06.283762+00', '{ODI,public_baseline,JTBD,reconstructed_prior,superseded_by_evidence_78e,superseded_by_evidence_79}', '[{"id": "s1", "title": "Define what operational proof means to partner cafe owners (interviews)", "status": "missing"}, {"id": "s2", "title": "Collect 90-day operational case evidence from 3 existing partners", "status": "missing"}, {"id": "s3", "title": "Share documented proof with prospective accounts and track response", "status": "missing"}, {"id": "s4", "title": "Review: did proof change purchasing confidence or repeat behavior?", "status": "missing"}]', '[{"id": "e1", "title": "Partner satisfaction and repeat purchase data (before proof)", "status": "missing"}, {"id": "e2", "title": "Partner satisfaction and repeat purchase data (after proof)", "status": "missing"}, {"id": "e3", "title": "Public signals baseline (specialty coffee buyer behavior)", "status": "complete"}, {"id": "e4", "title": "Direct interview evidence from cafe owner partners", "status": "missing"}]', '["Route fits a direction centered on partner operational outcomes and operational reliability, but current proof is mostly public signals — confidence should stay provisional.", "Whether buyers choose primarily on craft quality and specialty coffee positioning, partner operational outcomes, operational reliability, or some combination is still unclear and unresolved.", "Supplier switching must remain easy enough that proof gaps change behavior — maintain low switching cost as a design constraint while building this evidence.", "This route could weaken if buyers ultimately prioritize price or convenience more than reliability and proof — that risk has not yet been tested with direct customer evidence."]', 'stale', 'unvalidated', 'partial', NULL, 'Replaced by evidence-derived routes from Phase 79 active file analysis', NULL, NULL, NULL, '{}', '{}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('e1000001-cafe-4bcd-9012-cafe79000001', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', '5860c99a-e6f8-4feb-9997-992e3654f181', 'create', 'Build a seasonal consistency signal partner cafes can observe independently', 'Right now the exceptional quality claim requires a leap of faith. Alternatives are easy to sample. Create a verifiable consistency artifact — roast log, tasting guide, or comparison protocol — that surfaces the Barra Method''s quality ceiling before purchase commitment.', 0, 'medium', 'Improve', 10, '2026-05-13 22:14:06.283762+00', '2026-05-13 22:14:06.283762+00', '{ODI,evidence_derived_79}', '[{"id": "s1", "title": "Define what a consistency artifact looks like (roast log, tasting comparison, variance report)", "status": "missing"}, {"id": "s2", "title": "Pilot with one existing partner account: can they interpret and use the artifact?", "status": "missing"}, {"id": "s3", "title": "Determine whether the artifact survives seasonal origin transitions", "status": "missing"}]', '[{"id": "e1", "title": "Alternatives analysis: inconsistency cited as defining failure of craft alternatives", "status": "complete"}, {"id": "e2", "title": "Strategic Framework: positioning requires earned proof, not narrative", "status": "complete"}, {"id": "e3", "title": "Direct customer measurement of consistency perception", "status": "missing"}, {"id": "e4", "title": "Partner willingness to share drink quality tracking data", "status": "missing"}]', '["The alternatives analysis shows inconsistency is the defining failure of every craft alternative Cafe Barra competes against. Local artisan roasters are described as ''really good on Tuesdays'' — not a brand you can build on.", "Exceptional requires ongoing proof. The gap between really good and exceptional is qualitatively different — but invisible until experienced. A consistency signal closes that gap before commitment is required.", "No competing alternative has this artifact. Commodity roasters win on ease. Artisan roasters lose on variance. Neither produces a verifiable consistency record. This is uncontested ground."]', 'fresh', 'unvalidated', 'partial', NULL, NULL, NULL, NULL, '{"pressure": "Consistency Proof Pressure", "uncertainty": "No evidence in any active file measures whether partner cafes actually perceive Cafe Barra as more consistent than alternatives they have previously used. The quality claim is internally documented, not externally validated.", "prerequisites": ["At least one existing partner account willing to participate in a consistency tracking pilot", "Internal clarity on what consistency metrics the Barra Process already produces"], "pressure_short": "Consistency proof", "customer_impact": "A cafe owner can compare Cafe Barra consistency against their current roaster using a concrete artifact, not narrative. The decision to switch or deepen becomes evidence-based.", "evidence_snippets": [{"text": "The distance between really good and exceptional is qualitatively different — it is not a bigger version of the same thing, it is a different category of experience entirely.", "confidence": "direct", "source_label": "Alternatives Analysis", "source_file_id": "67c948c4-5b1c-4910-943e-9004f6db682b"}, {"text": "Local craft roasters: really good on Tuesdays is not a brand you can build on. The cafe owner ends up doing brand repair instead of brand building.", "confidence": "direct", "source_label": "Alternatives Analysis", "source_file_id": "67c948c4-5b1c-4910-943e-9004f6db682b"}, {"text": "Be the most trusted specialty coffee sourcing and roast development partner for independent cafe operators who want to build a distinctive offering.", "confidence": "direct", "source_label": "Strategic Framework Final", "source_file_id": "471a44bc-a868-4c1e-8f21-f8564e3a045a"}], "confidence_posture": "Signal is strong on the problem (alternatives fail on consistency). Signal is absent on the solution (no artifact exists yet, no partner has tested one). Proceed on problem confidence; solution confidence is zero until piloted.", "movement_condition": "Confidence strengthens when a partner uses the artifact and reports it changed their perception of Cafe Barra quality. Confidence weakens if no partner engages with it after two seasonal cycles.", "operational_impact": "Requires creating and maintaining a consistency documentation process that survives seasonal transitions. Adds ongoing documentation burden if not systematized.", "weakening_conditions": ["Cafe Barra has a bad season — seasonal origin adaptation produces lower quality than expected", "A well-funded craft competitor builds a similar consistency artifact first", "Partners do not want to track drink quality data — the artifact has no audience"]}', '{67c948c4-5b1c-4910-943e-9004f6db682b,471a44bc-a868-4c1e-8f21-f8564e3a045a,4f9761e9-8505-436a-884b-641689337edc}', '{b1000001-cafe-4bcd-9012-cafe79000001}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('e2000001-cafe-4bcd-9012-cafe79000001', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', '5860c99a-e6f8-4feb-9997-992e3654f181', 'fix', 'Add a lightweight pre-qualification tier before the full partner interview', 'The 8-criteria Partner Selection Framework is thorough. The full interview is also the only filter: there is no faster way to identify obviously misaligned accounts before investing evaluation time. A brief written or async screen would protect the interview for accounts that already show alignment signals.', 0, 'medium', 'Improve', 20, '2026-05-13 22:14:06.283762+00', '2026-05-13 22:14:06.283762+00', '{ODI,evidence_derived_79}', '[{"id": "s1", "title": "Identify where most inquiries originate and what signals they send before the interview", "status": "missing"}, {"id": "s2", "title": "Draft a 5-question async screen that surfaces brand intent and price orientation", "status": "missing"}, {"id": "s3", "title": "Test the screen against 5 past or current accounts to calibrate scoring", "status": "missing"}]', '[{"id": "e1", "title": "Partner Selection Framework: 8-criteria scorecard and full structured interview guide documented", "status": "complete"}, {"id": "e2", "title": "Partner Selection Framework: clear decline criteria documented (price-first, no training, transactional)", "status": "complete"}, {"id": "e3", "title": "Pre-qualification format tested and shown to correctly filter misaligned accounts", "status": "missing"}, {"id": "e4", "title": "Measurement of current inquiry quality — what share of inquiries are misaligned before interview", "status": "missing"}]', '["The Partner Selection Framework identifies clear decline criteria: prioritizes lowest price, refuses staff training, treats suppliers as interchangeable vendors. These signals are often observable before a structured interview — in how the inquiry arrives, what they lead with, what they do not ask.", "The full interview requires a collaborative, conversational tone — it is not designed to screen, only to evaluate. If unqualified accounts reach the interview, the instrument is being used for the wrong stage.", "Protecting evaluation capacity is not administrative overhead. Each full interview the Barra Process is used well for is a future partner gained. Each misallocated interview is partner capacity wasted."]', 'fresh', 'unvalidated', 'partial', NULL, NULL, NULL, NULL, '{"pressure": "Partner Qualification Pressure", "uncertainty": "No data on what share of current inquiries are misaligned before they reach the full interview. Unclear whether inquiry volume is large enough to justify a pre-qualification stage, or whether the problem is small enough to handle manually.", "prerequisites": ["A baseline picture of inquiry sources and quality (even anecdotal) before building a screen", "Agreement on what signals in a pre-qualification response indicate a likely misalignment"], "pressure_short": "Partner qualification", "customer_impact": "Well-qualified partner cafes get faster access to Cafe Barra''s evaluation — less time in the queue behind misaligned accounts.", "evidence_snippets": [{"text": "Decline partnerships if a cafe: prioritizes lowest price above quality, refuses staff training, treats suppliers as interchangeable vendors, cannot maintain basic quality standards, has chaotic communication or ordering processes.", "confidence": "direct", "source_label": "Partner Selection Framework", "source_file_id": "3a0b6c5e-c8c8-49cc-8551-5b83804c6dd5"}, {"text": "Score Interpretation: 32-40 = Ideal Cafe Barra Partner. 8-15 = Decline Partnership. The full scorecard requires a structured interview to complete.", "confidence": "direct", "source_label": "Partner Selection Framework", "source_file_id": "3a0b6c5e-c8c8-49cc-8551-5b83804c6dd5"}], "confidence_posture": "Strong signal on the problem structure (decline criteria are documented and specific). No signal yet on whether the problem is large enough to act on. Start with a count: how many inquiries in the last 12 months reached the full interview and were declined?", "movement_condition": "Confidence strengthens when a pre-filter accurately identifies misaligned accounts without requiring a full interview. Weakens if decline criteria are found to require full interview context to apply reliably.", "operational_impact": "Reduces full-interview load for clearly misaligned accounts. Requires maintaining the pre-qualification screen as a living document when decline criteria evolve.", "weakening_conditions": ["Inquiry volume is so low that any screen adds friction without saving meaningful time", "The decline criteria are not actually observable before the full interview — they only appear when probed"]}', '{3a0b6c5e-c8c8-49cc-8551-5b83804c6dd5}', '{b1000002-cafe-4bcd-9012-cafe79000002}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('e3000001-cafe-4bcd-9012-cafe79000001', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', '5860c99a-e6f8-4feb-9997-992e3654f181', 'improve', 'Externalize one Barra roasting template into observable, partner-communicable criteria', 'The Barra Process has 5 templates. Each is currently held in instinct and careful notes. Converting one template into observable, non-instinct criteria would test whether the quality ceiling can be documented without losing precision — and would give partner cafes something concrete to verify against.', 0, 'medium', 'Improve', 30, '2026-05-13 22:14:06.283762+00', '2026-05-13 22:14:06.283762+00', '{ODI,evidence_derived_79}', '[{"id": "s1", "title": "Select the most systematizable template (origin-based criteria rather than instinct-heavy)", "status": "missing"}, {"id": "s2", "title": "Write observable pass/fail criteria for each step — no instinct references", "status": "missing"}, {"id": "s3", "title": "Test: can another person produce an acceptable roast from criteria alone?", "status": "missing"}, {"id": "s4", "title": "Document gap between externalized output and instinct-guided output (if any)", "status": "missing"}]', '[{"id": "e1", "title": "Barra Process: 5 templates matched to bean origin and density — documented structure exists", "status": "complete"}, {"id": "e2", "title": "Barra Process: 3-sample test protocol — concrete enough to describe in steps", "status": "complete"}, {"id": "e3", "title": "A trained barista has followed the documented template without instinct-based guidance", "status": "missing"}, {"id": "e4", "title": "Quality outcome of externalized template matches instinct-guided roast", "status": "missing"}]', '["The Barra Process describes three sample roasts per batch, then intensive dialing-in using instinct, smell, look, and taste. The methodology exists. The transfer mechanism does not.", "Each template is matched to bean characteristics — larger/wetter beans (Brazil, Mexico) vs smaller/denser (Ethiopia). This origin-based logic is systematizable: it is based on observable bean properties, not subjective preference.", "If one template can be externalized successfully, the remaining four become a roadmap. If no template survives externalization without instinct, the quality ceiling is person-dependent — a structural risk."]', 'fresh', 'unvalidated', 'thin', NULL, NULL, NULL, NULL, '{"pressure": "Methodology Scalability Pressure", "uncertainty": "Whether the instinct component is separable from the quality outcome is unknown until tested. The methodology could be partially systematizable (the structural steps are) but ultimately instinct-dependent (the quality ceiling requires it).", "prerequisites": ["A test batch with someone who has not been trained in the Barra Process following documented criteria only", "A clear quality rubric to compare externalized vs instinct-guided roast output"], "pressure_short": "Methodology scalability", "customer_impact": "Partner cafes could receive a verification guide for each origin batch — moving quality assurance from trust in Cafe Barra to observable criteria they can check themselves.", "evidence_snippets": [{"text": "I have developed 5 main roasting templates that I use to decide if and how to roast each bean. Some templates are geared toward larger, wetter beans like Brazil or Mexico, while others work better with the smaller, denser beans like those from Ethiopia.", "confidence": "direct", "source_label": "The Barra Process", "source_file_id": "ec0c7a86-f085-4ea2-86dd-06fdb6a44f73"}, {"text": "It is in this last step that I lean heavily on instinct, paying close attention to the smell, look and taste of the beans as they are roasting while keeping careful notes on how to repeat this recipe. Science meets art meets commitment.", "confidence": "direct", "source_label": "The Barra Process", "source_file_id": "ec0c7a86-f085-4ea2-86dd-06fdb6a44f73"}], "confidence_posture": "The templates exist and are origin-based — systematization looks plausible. The instinct layer is the unknown. Run the test before drawing conclusions about scalability.", "movement_condition": "Confidence strengthens when a second person produces an acceptable roast from documented criteria without instinct-based guidance. Confidence weakens if every externalization attempt requires instinct correction.", "operational_impact": "If externalization succeeds, onboarding new partner baristas becomes documentable. If it fails, the person-dependency becomes a known structural constraint requiring different mitigation.", "weakening_conditions": ["The externalized template produces lower quality than the instinct-guided version — confirming the ceiling is person-dependent", "The process of writing observable criteria reveals that the judgment calls are too contextual to codify"]}', '{ec0c7a86-f085-4ea2-86dd-06fdb6a44f73}', '{b1000004-cafe-4bcd-9012-cafe79000004}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('e4000001-cafe-4bcd-9012-cafe79000001', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', '5860c99a-e6f8-4feb-9997-992e3654f181', 'fix', 'Design the seasonal origin transition so partner cafes experience it as a methodology feature, not a supply disruption', 'Seasonal variation is Cafe Barra''s intentional model — buy for a season, adapt to the bean. But partners experience this as an unexplained change unless briefed. The Barra Process''s strength becomes invisible noise unless communication design converts it into a visible proof of craft.', 0, 'medium', 'Improve', 40, '2026-05-13 22:14:06.283762+00', '2026-05-13 22:14:06.283762+00', '{ODI,evidence_derived_79}', '[{"id": "s1", "title": "Document what information a partner cafe would need to welcome rather than resist an origin transition", "status": "missing"}, {"id": "s2", "title": "Draft a one-page seasonal brief: what changed, why, what to expect in the cup", "status": "missing"}, {"id": "s3", "title": "Send to one partner account ahead of next seasonal transition and ask for feedback", "status": "missing"}]', '[{"id": "e1", "title": "Barra Process: seasonal adaptation philosophy documented explicitly", "status": "complete"}, {"id": "e2", "title": "Partner cafes currently receive seasonal transition briefings", "status": "missing"}, {"id": "e3", "title": "Partner feedback on how they experience origin transitions", "status": "missing"}]', '["The Barra Process states: my idea of consistency is not the same bean and same flavor profile every season, but instead consistent quality. This is the intended model. Whether partners understand and accept it as a model rather than experiencing it as inconsistency depends entirely on whether it is communicated as deliberate.", "Partners who do not understand the seasonal model may compare October''s coffee to July''s and experience degradation — exactly the failure mode of commodity alternatives. The positioning fails not because quality changed, but because the quality model was not communicated.", "The Alternatives Analysis shows that local artisan roasters lose accounts because of inconsistency that customers cannot distinguish from deliberate seasonal adaptation. Cafe Barra has the documentation to make this distinction visible. Using it proactively is a differentiation lever that requires no new capability — only communication design."]', 'fresh', 'unvalidated', 'partial', NULL, NULL, NULL, NULL, '{"pressure": "Seasonal Sourcing Pressure", "uncertainty": "No evidence in active files indicates whether current partner cafes actually experience seasonal transitions as positive, neutral, or disruptive. The problem may already be managed — or it may be causing silent attrition.", "prerequisites": ["One upcoming seasonal transition to use as a pilot for the briefing approach", "A partner account willing to give honest feedback on how they experience origin changes"], "pressure_short": "Seasonal sourcing", "customer_impact": "Partner cafes can brief their own staff on what changed and why — turning origin transitions from confusing variability into a story about seasonal craft. Reduces barista uncertainty and customer-facing inconsistency in messaging.", "evidence_snippets": [{"text": "My idea of consistency is not the same bean and same flavor profile every season, but instead consistent quality. Here is how I achieve this.", "confidence": "direct", "source_label": "The Barra Process", "source_file_id": "ec0c7a86-f085-4ea2-86dd-06fdb6a44f73"}, {"text": "When those beans run out, I attempt to acquire similar beans, but no two beans are alike. Instead of trying to adjust the roasts to make them taste similar to the previous batches, I choose to bring out the unique character of each bean.", "confidence": "direct", "source_label": "The Barra Process", "source_file_id": "ec0c7a86-f085-4ea2-86dd-06fdb6a44f73"}, {"text": "The local craft roaster alternative: really good on Tuesdays is not a brand you can build on. The gap between really good and exceptional is where inconsistency lives, and customers feel that gap even when they cannot name it.", "confidence": "direct", "source_label": "Alternatives Analysis", "source_file_id": "67c948c4-5b1c-4910-943e-9004f6db682b"}], "confidence_posture": "High confidence on the underlying problem structure — the methodology creates seasonal variation, and partners are not currently briefed on how to interpret it. No current evidence confirms this is causing friction. Test before investing in systematic brief infrastructure.", "movement_condition": "Confidence strengthens when a partner explicitly references the seasonal brief as helpful or shares it with their staff. Weakens if partners report they already handle transitions without briefing or do not find the distinction meaningful.", "operational_impact": "Requires a lightweight seasonal brief for each origin transition. Low ongoing cost if templatized. Creates a visible record of Cafe Barra''s methodology decisions over time.", "weakening_conditions": ["Partners prefer consistent flavor profiles over consistent quality — the distinction does not resonate with their customer base", "Seasonal briefs require more preparation time than current capacity allows each cycle"]}', '{ec0c7a86-f085-4ea2-86dd-06fdb6a44f73,67c948c4-5b1c-4910-943e-9004f6db682b}', '{b1000003-cafe-4bcd-9012-cafe79000003}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('e5000001-cafe-4bcd-9012-cafe79000001', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', '5860c99a-e6f8-4feb-9997-992e3654f181', 'create', 'Test whether the exceptional positioning holds under direct comparison with premium craft alternatives a prospect has already considered', 'The positioning places Cafe Barra above "really good" in a quality category that is "qualitatively different." This is asserted, not demonstrated. A prospect who has already tried Blue Bottle or Stumptown will compare, not defer. The positioning needs to survive that direct comparison — not just in narrative, but in what a prospect actually experiences.', 0, 'medium', 'Improve', 50, '2026-05-13 22:14:06.283762+00', '2026-05-13 22:14:06.283762+00', '{ODI,evidence_derived_79}', '[{"id": "s1", "title": "Identify a prospective partner currently using Blue Bottle or Stumptown for retail/hospitality", "status": "missing"}, {"id": "s2", "title": "Design a blind tasting protocol using the Barra Process to produce comparison samples", "status": "missing"}, {"id": "s3", "title": "Run comparison and document whether prospect perceives the exceptional vs really good distinction", "status": "missing"}]', '[{"id": "e1", "title": "Alternatives analysis: quality ceiling map with explicit position for Cafe Barra", "status": "complete"}, {"id": "e2", "title": "Strategic Framework: positioning statement as the specialty roast development partner", "status": "complete"}, {"id": "e3", "title": "Direct comparison result: prospect blind tasted Barra vs known premium alternative", "status": "missing"}, {"id": "e4", "title": "Partner account acquired from a competitor citing quality differentiation as deciding factor", "status": "missing"}]', '["The Alternatives Analysis identifies well-known craft brands (Blue Bottle, Stumptown, Equator) as the relevant comparison for specialty store buyers — not commodity distributors. These accounts carry brand recognition. Cafe Barra''s differentiation claim must survive comparison with these brands in a prospect''s direct experience, not just in a positioning deck.", "The quality ladder in the Alternatives Analysis places exceptional above really good as a qualitatively different category. This is correct framing. But the analysis does not establish whether Cafe Barra has crossed that line from the perspective of a prospect who has not yet experienced the Barra Process.", "Positioning that cannot be tested is positioning that cannot be trusted. If the exceptional claim holds under direct comparison, it becomes a closing argument. If it does not, the claim needs to be revised before it creates expectation gaps with partners."]', 'fresh', 'unvalidated', 'thin', NULL, NULL, NULL, NULL, '{"pressure": "Brand Coherence Pressure", "uncertainty": "No active file contains evidence of how prospects actually perceive Cafe Barra quality relative to premium craft brands they have already experienced. The positioning is internally constructed — no external validation exists yet.", "prerequisites": ["At least one batch of recent Cafe Barra coffee produced by the Barra Process for comparison", "A prospective partner who has direct experience with a premium craft alternative and is willing to do a comparison"], "pressure_short": "Brand coherence", "customer_impact": "If the test succeeds: a new partner acquisition argument grounded in direct experience rather than narrative. If it fails: early identification that the quality ceiling claim needs revision before it creates expectation gaps.", "evidence_snippets": [{"text": "The quality ladder: Alternative quality ceiling — National/regional commodity: good enough. Local artisan: really good (inconsistently). In-house: variable. The distance between good and really good is where regulars come from. But the distance between really good and exceptional is qualitatively different — it is not a bigger version of the same thing.", "confidence": "direct", "source_label": "Alternatives Analysis", "source_file_id": "67c948c4-5b1c-4910-943e-9004f6db682b"}, {"text": "Well-known regional or national craft brands (Blue Bottle, Stumptown, Equator) — these bring brand recognition but also dilute the store''s own identity. You are carrying their story, not telling yours.", "confidence": "direct", "source_label": "Alternatives Analysis", "source_file_id": "67c948c4-5b1c-4910-943e-9004f6db682b"}, {"text": "The roast partner for cafes that take quality seriously.", "confidence": "direct", "source_label": "Strategic Framework Final", "source_file_id": "471a44bc-a868-4c1e-8f21-f8564e3a045a"}], "confidence_posture": "Positioning claim is coherent and internally consistent. External validation is completely absent. Confidence in the claim should be treated as directional until a comparison test produces evidence in either direction.", "movement_condition": "Confidence strengthens when a prospect who has experienced a premium craft alternative chooses Cafe Barra citing quality differentiation. Weakens if multiple comparison tests produce no perceived distinction.", "operational_impact": "Requires producing comparison-quality samples on demand. Low investment for a one-time test. High value if it confirms or refutes the positioning claim.", "weakening_conditions": ["A prospect blind tastes Cafe Barra and Blue Bottle and cannot distinguish them reliably", "The Barra Process produces exceptional quality only in specific origins — not across all seasonal variants", "Premium alternatives have already communicated a similar exceptional framing — the positioning is not distinctive to prospects"]}', '{67c948c4-5b1c-4910-943e-9004f6db682b,471a44bc-a868-4c1e-8f21-f8564e3a045a,0337c3b9-b682-48b6-a6c1-c176b1f8633d}', '{b1000001-cafe-4bcd-9012-cafe79000001}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('ecf0b2e3-b5ec-4bb6-9327-e801071b110b', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', 'fd766480-d2ef-4794-a79a-b849a91df024', 'fix', 'Make margin tradeoffs visible before pricing changes', 'Menu pricing evolved ad-hoc with no documented model linking cost, volume, and target margin. Tradeoffs are invisible until they show up as profitability surprises.', 8, 'medium', 'Fix', 2, '2026-05-13 19:04:00.517997+00', '2026-05-13 22:14:06.283762+00', '{ODI,public_baseline,reconstructed_prior,superseded_by_evidence_78e,superseded_by_evidence_79}', '[{"id": "s1", "title": "Pull COGS data for top 20 SKUs from invoices and POS", "status": "complete"}, {"id": "s2", "title": "Build target margin model by product category", "status": "in_progress"}, {"id": "s3", "title": "Publish pricing floor guide for internal use", "status": "missing"}, {"id": "s4", "title": "Validate model against last 3 months of actuals", "status": "missing"}]', '[{"id": "e1", "title": "POS sales export (last 6 months)", "status": "complete"}, {"id": "e2", "title": "Cost invoice records", "status": "complete"}, {"id": "e3", "title": "Competitor menu pricing sample for specialty segment", "status": "in_progress"}, {"id": "e4", "title": "Documented, signed-off pricing model", "status": "missing"}]', '["Without a margin model, pricing decisions are reactive and may offset gains from volume or quality improvement.", "Defining floor margins per product category creates a consistent decision rule before any pricing change.", "Margin visibility is a precondition for credible pricing conversations with cafe owner partners."]', 'stale', 'unvalidated', 'partial', NULL, 'Replaced by evidence-derived routes from Phase 79 active file analysis', NULL, NULL, NULL, '{}', '{}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('111d3d7f-22b4-4fcb-9b8f-c5dd9219e670', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', 'fd766480-d2ef-4794-a79a-b849a91df024', 'improve', 'Shift preparation quality from manager-dependent to system-supported', 'Preparation quality consistency currently depends on manager presence and informal training. Building system-level support removes the single point of failure.', 6, 'low', 'Improve', 3, '2026-05-13 19:04:00.517997+00', '2026-05-13 22:14:06.283762+00', '{ODI,JTBD,reconstructed_prior,superseded_by_evidence_78e,superseded_by_evidence_79}', '[{"id": "s1", "title": "Shadow top-performing shifts to document current best practice", "status": "complete"}, {"id": "s2", "title": "Draft written prep checklist per station", "status": "in_progress"}, {"id": "s3", "title": "Pilot checklist with two shifts and collect staff feedback", "status": "missing"}, {"id": "s4", "title": "Roll out finalized standards and post at each station", "status": "missing"}]', '[{"id": "e1", "title": "Customer complaint log (last quarter, quality-related)", "status": "complete"}, {"id": "e2", "title": "Staff satisfaction and consistency self-assessment", "status": "in_progress"}, {"id": "e3", "title": "Finalized written prep standards document", "status": "missing"}]', '["Standardized prep removes the manager-as-single-point-of-failure dependency — quality holds when the owner is not in the building.", "Written systems scale onboarding and reduce quality variance across staff and shifts.", "Directly addresses the operational reliability gap that weakens partner confidence in our offering."]', 'stale', 'unvalidated', 'partial', NULL, 'Replaced by evidence-derived routes from Phase 79 active file analysis', NULL, NULL, NULL, '{}', '{}', '{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.routes (id, company_id, user_id, category, title, short_description, pts_value, effort, type, sort_order, created_at, updated_at, frameworks_used, steps_json, evidence_json, why_this_matters_json, dependency_state, validation_state, evidence_state, last_reviewed_at, stale_reason, stale_since_event_id, source_run_id, route_insights_json, source_file_ids, linked_tension_ids, linked_need_ids) VALUES ('6dacee4b-af44-415d-be93-7e8b430fd6ca', '58b2b15b-bada-4bcd-9c12-b7e66a37d0bc', 'fd766480-d2ef-4794-a79a-b849a91df024', 'improve', 'Reduce stock-out risk before manual counts fail', 'Ordering decisions rely on manual counts with no connection to sales velocity. Stock-outs may be detected only after they occur — leaving cafe partners without supply.', 7, 'medium', 'Improve', 4, '2026-05-13 19:04:00.517997+00', '2026-05-13 22:14:06.283762+00', '{strategy_cascade,JTBD,reconstructed_prior,superseded_by_evidence_78e,superseded_by_evidence_79}', '[{"id": "s1", "title": "Audit POS system for inventory module or API availability", "status": "complete"}, {"id": "s2", "title": "Map top 15 SKUs to par levels and reorder points", "status": "in_progress"}, {"id": "s3", "title": "Configure par level alerts in POS or inventory tool", "status": "missing"}, {"id": "s4", "title": "Run 30-day trial and validate alert timing against actuals", "status": "missing"}]', '[{"id": "e1", "title": "POS system feature documentation", "status": "complete"}, {"id": "e2", "title": "Historical stock-out events (6 months) with root cause notes", "status": "in_progress"}, {"id": "e3", "title": "Par level configuration live and validated", "status": "missing"}]', '["Manual counts introduce lag — stock-outs likely surface hours after the actual tipping point, affecting partner orders.", "A POS-linked par level model makes ordering consistent and less dependent on daily individual judgment.", "Reducing supply disruption risk is foundational to the operational reliability positioning we are claiming."]', 'stale', 'unvalidated', 'partial', NULL, 'Replaced by evidence-derived routes from Phase 79 active file analysis', NULL, NULL, NULL, '{}', '{}', '{}') ON CONFLICT (id) DO NOTHING;

-- 3. promote all CB routes to level='route' (only the 10 remain after step 1) so hasHierarchy holds
UPDATE public.routes SET level='route' WHERE company_id='58b2b15b-bada-4bcd-9c12-b7e66a37d0bc';

-- 4. renumber sort_order 1-10 by their original ordering
WITH ord AS (SELECT id, row_number() OVER (ORDER BY sort_order, created_at) AS rn
             FROM public.routes WHERE company_id='58b2b15b-bada-4bcd-9c12-b7e66a37d0bc')
UPDATE public.routes r SET sort_order = ord.rn FROM ord WHERE r.id = ord.id;

COMMIT;

-- verification (expect 10 rows, all level=route, relevance_state=active):
SELECT sort_order, level, relevance_state, left(title,60) AS title
FROM public.routes WHERE company_id='58b2b15b-bada-4bcd-9c12-b7e66a37d0bc' ORDER BY sort_order;
